INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66276162', 66276162, 'analyze_legacy', 'Kab. Bandung', 'kabkota', 'DINAS PEKERJAAN UMUM DAN TATA RUANG', 'Dokumen Lingkungan Jalan Kabupaten Wilayah Selatan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kab.)', 100000000, 'March 2026', 'APBD', 1, 1, '1 Paket', 'a. Mengidentifikasi penapisan dokumen lingkungan UKL-UPL / AMDAL; b. Melaksanakan survey lokasi, mengidentifikasi dan mengumpulkan data primer serta sekunder terkait kondisi fisik, biologi, sosial, ekonomi, dan budaya di lokasi proyek; c. Melakukan analisis menyeluruh terhadap potensi dampak lingkungan dari aktivitas proyek pada tahap konstruksi dan operasional; d. Mengidentifikasi potensi dampak positif dan negative yang mungkin terjadi, baik terhadap lingkungan fisik, ekosistem, maupun kehidupan sosial masyarakat sekitar; e. Merumuskan langkah-langkah mitigasi untuk meminimalkan dampak negatif serta merancang program pemantauan yang efektif selama proyek berlangsung; f. Mengidentifikasi risiko Keselamatan dan Kesehatan Kerja (K3) Proyek dan Menyusun program Keselamatan dan Kesehatan Kerja (K3) Proyek padatahap konstruksi dan operasional; g. Melakukan konsultasi publik dan mendapatkan masukan dari masyarakat serta pemangku kepentingan terkait proyek dan dampaknya; h. Melaksanakan rapat koordinasi dengan instansi terkait, dalam rangka pengurusan dokumen lingkungan; i. Menyusun data geospasial lokasi kegiatan dalam format shapefile/GIS; j. Menyusun dokumen lingkungan, lengkap dengan hasil kajian dan rekomendasi, melakukan pendampingan kepada Dinas Pekerjaan Umum dan Tata Ruang dalam rangka proses persetujuan dokumen lingkungan, serta menyampaikan laporan tersebut kepada pihak berwenang untuk proses persetujuan;', 'Memastikan bahwa semua aspek proyek memenuhi persyaratan dan standar yang ditetapkan dalam peraturan perundang-undangan terkait lingkungan hidup 1. Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah 2. Undang-Undang Nomor 32 Tahun 2009 tentang Perlindungan dan Pengelolaan Lingkungan Hidup 3. Peraturan Pemerintah Nomor 22 Tahun 2021 tentang Penyelenggaraan Perlindungan dan Pengelolaan Lingkungan Hidup 4. Peraturan Menteri Lingkungan Hidup Dan Kehutanan Republik Indonesia Nomor 4 Tahun 2021 Tentang Daftar Usaha Dan/Atau Kegiatan Yang Wajib Memiliki Analisis Mengenai Dampak Lingkungan Hidup, Upaya Pengelolaan Lingkungan Hidup Dan Upaya Pemantauan Lingkungan Hidup Atau Surat Pernyataan Kesanggupan Pengelolaan Dan Pemantauan Lingkungan Hidup 5. Peraturan perundang-undangan pengelolaan lingkungan hidup yang berlaku', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2650196);
