INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66314481', 66314481, 'analyze_legacy', 'Kementerian Perumahan dan Kawasan Permukiman', 'central', 'Direktorat Jenderal Perumahan Perdesaan Kementerian Perumahan dan Kawasan Permukiman', 'Pengadaan Jasa EO', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 93150000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Penyediaan jasa penyelenggaraan acara dalam rangka mendukung pelaksanaan kegiatan Town Hall Meeting Peningkatan Kapasitas Pegawai di Lingkungan Direktorat Jenderal Perumahan Perdesaan', 'Konsumsi rapat (makan dan kudapan untuk kegiatan rapat/seminar/sejenisnya yang dilaksanakan sehari penuh) sebanyak 300 pax; seminar kit sebanyak 300 pcs yang terdiri dari peralatan penyuara jemala dengan teknologi true wireless stereo (TWS) konektivitas bluetooth (150 pcs) dan peralatan mouse nirkabel bahan plastik ABS dengan teknologi nano mini reciever koneksi bluetooth (150 pcs); sewa peralatan pendukung rapat berupa bean bag berbentuk segitiga ukuran 900mm x 1300mm x 900mm sebanyak 150 pcs dan bantal duduk berbentuk persegi ukuran 40cm x 40cm sebanyak 150 pcs; serta jasa tenaga pendukung penyelenggaraan acara yang berpengalaman sebanyak 5 orang yang terdiri dari project leader (1 orang), tim logistik (2 orang), tim hospitality (2 orang), beserta biaya operasional tenaga/tim pendukung', 46500000, 'high', 'Terdapat indikasi pengadaan item penunjang yang kurang relevan dan berpotensi tidak efisien untuk kegiatan peningkatan kapasitas pegawai, khususnya seminar kit berupa TWS dan mouse nirkabel serta sewa bean bag dan bantal duduk dalam jumlah besar. Komponen tersebut lebih menyerupai barang konsumtif/promosi dibanding kebutuhan inti rapat atau town hall, sehingga patut diduga menimbulkan pemborosan anggaran.', NULL, NULL, 3, 1, 1, 1, 1, 2652315);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66277266', 66277266, 'analyze_legacy', 'Kab. Indragiri Hilir', 'kabkota', 'BADAN KESATUAN BANGSA DAN POLITIK', 'Belanja Jasa Konsultansi Pengawasan Pembagunan Pantai (Turap Taman) dan Renovasi Bangunan Kantor Pos TNI AL Tanjung Datuk', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Riau, Indragiri Hilir (Kab.)', 12000000, 'March 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Jasa Konsultansi Pengawasan;', 'Arsitektur-Jasa Arsitektur Lainnya; sesuai kak', 12000000, 'high', 'Objek pengadaan berupa pengawasan pembangunan pantai dan renovasi kantor pos TNI AL tampak tidak selaras dengan fungsi umum perangkat daerah bidang kesatuan bangsa dan politik. Dari judul dan konteks, terdapat indikasi kuat belanja konsultansi ini berada di luar mandat utama sehingga patut dinilai sebagai penggunaan anggaran yang berisiko tidak tepat sasaran.', NULL, NULL, 3, 1, 1, 1, 1, 2652316);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66277306', 66277306, 'analyze_legacy', 'Kab. Indragiri Hilir', 'kabkota', 'BADAN KESATUAN BANGSA DAN POLITIK', 'Pembangunan Mess Kejaksaan Negeri Tembilahan JL Tanjung Harapan Lr. Tanjung Beringin', 'Pekerjaan Konstruksi', 'Tender', 'Riau, Indragiri Hilir (Kab.)', 700000000, 'March 2026', 'APBD', 1, 1, '1 Paket', 'Pembangunan Mess Kejaksaan Negeri Tembilahan JL Tanjung Harapan Lr. Tanjung Beringin;', 'Panjang 16 M X L 15,5 M;', 700000000, 'high', 'Pembangunan mess untuk instansi kejaksaan oleh satuan kerja bidang kesatuan bangsa dan politik terindikasi kurang selaras dengan fungsi utama belanja perangkat daerah. Dari judul dan uraian, pengadaan berupa pembangunan fasilitas hunian/akomodasi bagi instansi lain sehingga relevansi penggunaan APBD melalui satker ini patut dipertanyakan secara serius.', NULL, NULL, 3, 1, 1, 1, 1, 2652317);
