INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66321061', 66321061, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Obat Kusta Frambusia tahun 2026 (Obat Lepasan untuk MDT Anak)', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 1472364426, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Obat Kusta Frambusia berupa MDT Anak : 1 .Rifampisin 300 mg sebanyak 33100 Tablet/kapsul/Kaplet dengan estimasi harga satuan Rp3,553.73 2 .Rifampisin 150 mg sebanyak 33100 Tablet/kapsul/Kaplet dengan estimasi harga satuan Rp1,880.23 3 .Klofazimin 50 mg sebanyak 529400 Tablet/kapsul/Kaplet dengan estimasi harga satuan Rp1,724.49 4 .Dapson 50 mg sebanyak 926400 Tablet/kapsul/Kaplet dengan estimasi harga satuan Rp409.71', 'Spesifikasi Obat Kusta Frambusia sebagai berikut : a) RIFAMPISIN 300 mg : 1. Nama Zat Aktif : Rifampisin 300 mg, 2. Bentuk Sediaan : Tablet/kaplet/kapsul, 3. Kemasan : Blister/strip/botol, 4. Komposisi : Setiap tablet/kaplet/kapsul mengandung 300 mg rifampisin, 5. Masa Kadaluarsa : Shelf life lebih dari 24 bulan maka masa kadaluarsa minimal 24 bulan, jika shelf life sama dengan 24 bulan maka kadaluarsa minimal 18 bulan, 6. Izin Edar : Produk Obat wajib memiliki Nomor Izin Edar (NIE) atau SAS yang dikeluarkan oleh BPOM RI/Kemenkes RI dan yang masih berlaku, dengan melampirkan NIE atau SAS dan informasi produk. b) RIFAMPISIN 150 mg 1. Nama Zat Aktif : Rifampisin 150 mg, 2. Bentuk Sediaan : Tablet/kaplet/kapsul, 3. Kemasan : Blister/strip/botol, 4. Komposisi : Setiap tablet/kaplet/kapsul mengandung 150 mg rifampisin, 5. Masa Kadaluarsa : Shelf life lebih dari 24 bulan maka masa kadaluarsa minimal 24 bulan, jika shelf life sama dengan 24 bulan maka kadaluarsa minimal 18 bulan, 6. Izin Edar : Produk Obat wajib memiliki Nomor Izin Edar (NIE) atau SAS yang dikeluarkan oleh BPOM RI/Kemenkes RI dan yang masih berlaku, dengan melampirkan NIE atau SAS dan informasi produk. c) KLOFAZIMIN : 1. Nama Zat Aktif : Klofazimin 50 mg, 2. Bentuk Sediaan : Tablet/kaplet/kapsul, 3. Kemasan : Blister/strip/botol, 4. Komposisi : Setiap tablet/kaplet/kapsul mengandung 50 mg klofazimin, 5. Masa Kadaluarsa : Shelf life lebih dari 24 bulan maka masa kadaluarsa minimal 24 bulan, jika shelf life sama dengan 24 bulan maka kadaluarsa minimal 18 bulan, 6. Izin Edar : Produk Obat wajib memiliki Nomor Izin Edar (NIE) atau SAS yang dikeluarkan oleh BPOM RI/Kemenkes RI dan yang masih berlaku, dengan melampirkan NIE atau SAS dan informasi produk. 7. Jumlah usulan : Sesuai dengan paket MDT, PPK dapat melakukan pembulatan jumlah ke atas yang disediakan ke kemasan terkecil yang dimiliki penyedia. d) DAPSON : 1. Nama Zat Aktif : Dapson 50 mg, 2. Bentuk Sediaan : Tablet/kaplet/kapsul, 3. Kemasan : Blister/strip/botol, 4. Komposisi : Setiap tablet/kaplet/kapsul mengandung 50 mg dapson, 5. Masa Kadaluarsa : Shelf life lebih dari 24 bulan maka masa kadaluarsa minimal 24 bulan, jika shelf life sama dengan 24 bulan maka kadaluarsa minimal 18 bulan, 6. Izin Edar : Produk Obat wajib memiliki Nomor Izin Edar (NIE) atau SAS yang dikeluarkan oleh BPOM RI/Kemenkes RI dan yang masih berlaku, dengan melampirkan NIE atau SAS dan informasi produk. 7. Jumlah usulan : sesuai dengan paket MDT, PPK dapat melakukan pembulatan jumlah ke atas yang disediakan ke kemasan terkecil yang dimiliki penyedia.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2657802);
